// ---------------------------------------------------------------------------
// In-memory sliding window rate limiter for public API endpoints
// ---------------------------------------------------------------------------

interface RateLimitEntry {
  count: number;
  resetAt: number;
}

const store = new Map<string, RateLimitEntry>();

// Cleanup stale entries every 5 minutes to prevent memory leaks
const CLEANUP_INTERVAL = 5 * 60 * 1000;
let lastCleanup = Date.now();

function cleanup(): void {
  const now = Date.now();
  if (now - lastCleanup < CLEANUP_INTERVAL) return;
  lastCleanup = now;
  for (const [key, entry] of store) {
    if (entry.resetAt <= now) {
      store.delete(key);
    }
  }
}

/**
 * Check rate limit for a given key (typically "endpoint:shop").
 * Returns null if under limit, or a Response (429) if over limit.
 */
export function checkRateLimit(
  key: string,
  maxRequests: number,
  windowMs: number = 60_000,
): Response | null {
  cleanup();

  const now = Date.now();
  const entry = store.get(key);

  if (!entry || entry.resetAt <= now) {
    store.set(key, { count: 1, resetAt: now + windowMs });
    return null;
  }

  entry.count++;

  if (entry.count > maxRequests) {
    const retryAfter = Math.ceil((entry.resetAt - now) / 1000);
    return Response.json(
      { error: "Too many requests. Please try again later." },
      {
        status: 429,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type",
          "Retry-After": String(retryAfter),
        },
      },
    );
  }

  return null;
}

export interface Plan {
  id: string;
  name: string;
  price: number;
  interval: string;
  annualPrice: number;
  features: string[];
  limits: {
    maxCharts: number;
    csvImport: boolean;
    autoAssign: boolean;
    translateAdapt: boolean;
    analytics: boolean;
    aiRecommender: boolean;
    advancedAi: boolean;
    returnAttribution: boolean;
    prioritySupport: boolean;
    multiStore: boolean;
    dedicatedSizingPage: boolean;
    imageInCharts: boolean;
  };
}

export const PLANS: Plan[] = [
  {
    id: "free",
    name: "Free",
    price: 0,
    interval: "month",
    annualPrice: 0,
    features: [
      "3 published size charts",
      "All templates",
