    price: 4.99,
    interval: "month",
    annualPrice: 47.90,
    features: [
      "Unlimited size charts",
      "CSV import / export",
      "Auto-assignment rules",
      "Image support in charts",
      "Translate & Adapt",
    ],
    limits: {
      maxCharts: -1, // unlimited
      csvImport: true,
      autoAssign: true,
      translateAdapt: true,
      analytics: false,
      aiRecommender: false,
      advancedAi: false,
      returnAttribution: false,
      prioritySupport: false,
      multiStore: false,
      dedicatedSizingPage: false,
      imageInCharts: true,
    },
  },
  {
    id: "growth",
    name: "Growth",
    price: 9.99,
    interval: "month",
    annualPrice: 95.90,
    features: [
      "Everything in Starter",
      "Basic AI size recommender",
      "Analytics dashboard",
      "Google Analytics integration",
      "Dedicated sizing page",
      "20+ language support",
    ],
    limits: {
      maxCharts: -1,
      csvImport: true,
      autoAssign: true,
      translateAdapt: true,
      analytics: true,
      aiRecommender: true,
      advancedAi: false,
      returnAttribution: false,
      prioritySupport: false,
      multiStore: false,
      dedicatedSizingPage: true,
      imageInCharts: true,
    },
  },
  {
    id: "pro",
    name: "Pro",
    price: 19.99,
    interval: "month",
    annualPrice: 191.90,
    features: [
      "Everything in Growth",
      "Advanced ML recommender",
      "AI auto-chart generation",
      "Return attribution analytics",
      "Priority support (<2hr)",
      "Multi-store sync",
    ],
    limits: {
