import { describe, it, expect } from "vitest";
import { getPlan, hasFeature, canCreateChart, PLANS } from "~/lib/plans";

describe("getPlan", () => {
  it("returns the Free plan for id 'free'", () => {
    const plan = getPlan("free");
    expect(plan.id).toBe("free");
    expect(plan.name).toBe("Free");
    expect(plan.price).toBe(0);
  });

  it("returns the correct plan for each known id", () => {
    for (const p of PLANS) {
      expect(getPlan(p.id).id).toBe(p.id);
    }
  });

  it("falls back to Free for unknown plan id", () => {
    const plan = getPlan("nonexistent");
    expect(plan.id).toBe("free");
  });
});

describe("hasFeature", () => {
