import { describe, it, expect } from "vitest";
import {
  validateShop,
  corsJson,
  corsOptions,
  sanitizeCss,
  CORS_HEADERS,
  SHOP_RE,
} from "~/lib/api.server";

describe("SHOP_RE regex", () => {
  it("matches valid shop domains", () => {
    expect(SHOP_RE.test("my-store.myshopify.com")).toBe(true);
    expect(SHOP_RE.test("store123.myshopify.com")).toBe(true);
    expect(SHOP_RE.test("a.myshopify.com")).toBe(true);
  });

  it("rejects domains not ending in .myshopify.com", () => {
    expect(SHOP_RE.test("store.notshopify.com")).toBe(false);
    expect(SHOP_RE.test("store.myshopify.com.evil.com")).toBe(false);
  });

  it("rejects domains starting with a hyphen", () => {
    expect(SHOP_RE.test("-bad.myshopify.com")).toBe(false);
  });

  it("rejects empty strings", () => {
    expect(SHOP_RE.test("")).toBe(false);
  });
});

describe("validateShop", () => {
  it("returns null for a valid shop domain", () => {
    expect(validateShop("test-store.myshopify.com")).toBeNull();
  });

  it("returns 400 response for null", () => {
    const res = validateShop(null);
    expect(res).toBeInstanceOf(Response);
    expect(res!.status).toBe(400);
  });

  it("returns 400 response for empty string", () => {
    const res = validateShop("");
    expect(res).toBeInstanceOf(Response);
    expect(res!.status).toBe(400);
  });

  it("returns 400 for invalid domain format", () => {
    const res = validateShop("not-a-shopify-domain.com");
    expect(res).toBeInstanceOf(Response);
    expect(res!.status).toBe(400);
  });

  it("400 response includes CORS headers", async () => {
    const res = validateShop(null)!;
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });

  it("400 response body has error message", async () => {
    const res = validateShop(null)!;
    const body = await res.json();
    expect(body.error).toContain("Invalid");
  });
});

describe("corsJson", () => {
  it("returns 200 by default", () => {
    const res = corsJson({ ok: true });
    expect(res.status).toBe(200);
  });

  it("includes CORS headers", () => {
    const res = corsJson({ ok: true });
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
    expect(res.headers.get("Access-Control-Allow-Methods")).toContain("GET");
    expect(res.headers.get("Access-Control-Allow-Headers")).toContain(
      "Content-Type",
    );
  });

  it("respects custom status", () => {
    const res = corsJson({ error: "not found" }, { status: 404 });
    expect(res.status).toBe(404);
  });

  it("merges custom headers", () => {
    const res = corsJson({}, { headers: { "Cache-Control": "no-cache" } });
    expect(res.headers.get("Cache-Control")).toBe("no-cache");
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });

  it("returns valid JSON body", async () => {
    const res = corsJson({ a: 1, b: "two" });
    const body = await res.json();
    expect(body).toEqual({ a: 1, b: "two" });
  });
});

describe("corsOptions", () => {
  it("returns 204 status", () => {
    const res = corsOptions();
    expect(res.status).toBe(204);
  });

  it("includes CORS headers", () => {
    const res = corsOptions();
    for (const [key, value] of Object.entries(CORS_HEADERS)) {
      expect(res.headers.get(key)).toBe(value);
    }
  });

  it("has null body", async () => {
    const res = corsOptions();
    expect(res.body).toBeNull();
  });
});

describe("sanitizeCss", () => {
  it("passes through safe CSS", () => {
    expect(sanitizeCss("body { color: red; }")).toBe("body { color: red; }");
  });

  it("returns empty string for empty input", () => {
    expect(sanitizeCss("")).toBe("");
  });

  it("blocks @import", () => {
    const result = sanitizeCss("@import url('evil.css');");
    expect(result).not.toContain("@import");
  });

  it("blocks javascript: in url()", () => {
    const result = sanitizeCss("background: url(javascript:alert(1))");
    expect(result).not.toContain("javascript:");
  });

  it("blocks data:text/html in url()", () => {
    const result = sanitizeCss("background: url(data:text/html,<h1>xss</h1>)");
    expect(result).not.toContain("data:text/html");
  });

  it("blocks expression()", () => {
    const result = sanitizeCss("width: expression(alert(1))");
    expect(result).not.toContain("expression(");
  });

  it("blocks behavior:", () => {
    const result = sanitizeCss("behavior: url(xss.htc)");
    expect(result).not.toContain("behavior:");
  });

  it("blocks -moz-binding:", () => {
    const result = sanitizeCss("-moz-binding: url(evil.xml#xss)");
    expect(result).not.toContain("-moz-binding:");
  });

  it("blocks <script> tags", () => {
    const result = sanitizeCss("</style><script>alert(1)</script>");
    expect(result).not.toContain("<script");
    expect(result).not.toContain("</style");
  });
});

