import { describe, it, expect, vi, beforeEach } from "vitest";

// The rate limiter uses a module-level Map, so we need to isolate between tests.
// We re-import dynamically to reset state or accept shared state and use unique keys.

let checkRateLimit: typeof import("~/lib/rate-limit.server").checkRateLimit;

beforeEach(async () => {
  // Dynamic import to get the function. Module state persists across tests in
  // the same file, so we use unique keys per test to avoid collisions.
  const mod = await import("~/lib/rate-limit.server");
  checkRateLimit = mod.checkRateLimit;
});

describe("checkRateLimit", () => {
  it("allows the first request", () => {
    const result = checkRateLimit("test-first-" + Date.now(), 10, 60_000);
    expect(result).toBeNull();
  });

  it("allows requests up to the limit", () => {
    const key = "test-under-limit-" + Date.now();
    for (let i = 0; i < 5; i++) {
      expect(checkRateLimit(key, 5, 60_000)).toBeNull();
    }
  });

  it("returns 429 when limit is exceeded", () => {
    const key = "test-exceeded-" + Date.now();
    // Use up the limit
    for (let i = 0; i < 3; i++) {
      checkRateLimit(key, 3, 60_000);
    }
    // Next request should be blocked
    const result = checkRateLimit(key, 3, 60_000);
    expect(result).toBeInstanceOf(Response);
    expect(result!.status).toBe(429);
  });

  it("429 response has Retry-After header", () => {
    const key = "test-retry-after-" + Date.now();
    for (let i = 0; i < 2; i++) {
      checkRateLimit(key, 2, 60_000);
    }
    const result = checkRateLimit(key, 2, 60_000)!;
    expect(result.headers.get("Retry-After")).toBeTruthy();
    const retryAfter = Number(result.headers.get("Retry-After"));
    expect(retryAfter).toBeGreaterThan(0);
    expect(retryAfter).toBeLessThanOrEqual(60);
  });

  it("429 response has CORS headers", () => {
    const key = "test-cors-429-" + Date.now();
    for (let i = 0; i < 1; i++) {
      checkRateLimit(key, 1, 60_000);
    }
    const result = checkRateLimit(key, 1, 60_000)!;
    expect(result.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });

  it("429 response has error message in body", async () => {
    const key = "test-body-429-" + Date.now();
    checkRateLimit(key, 1, 60_000);
    const result = checkRateLimit(key, 1, 60_000)!;
    const body = await result.json();
    expect(body.error).toContain("Too many requests");
  });

  it("isolates different keys", () => {
    const keyA = "test-isolate-A-" + Date.now();
    const keyB = "test-isolate-B-" + Date.now();
    // Exhaust key A
    checkRateLimit(keyA, 1, 60_000);
    const blockedA = checkRateLimit(keyA, 1, 60_000);
    expect(blockedA).toBeInstanceOf(Response);

    // Key B should still be allowed
    const allowedB = checkRateLimit(keyB, 1, 60_000);
    expect(allowedB).toBeNull();
  });

  it("resets after window expires", () => {
    vi.useFakeTimers();
    try {
      const key = "test-window-reset-" + Math.random();
      // Exhaust the limit
      checkRateLimit(key, 2, 1000);
      checkRateLimit(key, 2, 1000);
      expect(checkRateLimit(key, 2, 1000)).toBeInstanceOf(Response);

      // Advance time past the window
      vi.advanceTimersByTime(1100);

      // Should be allowed again
      expect(checkRateLimit(key, 2, 1000)).toBeNull();
    } finally {
      vi.useRealTimers();
    }
  });
});

