import { describe, it, expect, vi, beforeEach } from "vitest";
import {
  makeGetRequest,
  makeOptionsRequest,
  makeSizeChart,
  makeChartAssignment,
  TEST_SHOP,
} from "./helpers";

// Mock the db module
vi.mock("~/db.server", () => ({
  default: {
    sizeChart: {
      findFirst: vi.fn(),
    },
    chartAssignment: {
      findMany: vi.fn(),
    },
  },
}));

// Mock rate limiter to not interfere with tests
vi.mock("~/lib/rate-limit.server", () => ({
  checkRateLimit: vi.fn(() => null),
}));

import { loader } from "~/routes/api.size-chart";
import db from "~/db.server";

const BASE_URL = "http://localhost:3000/api/size-chart";

beforeEach(() => {
  vi.clearAllMocks();
});

describe("GET /api/size-chart", () => {
  it("returns 400 when shop param is missing", async () => {
    const req = makeGetRequest(BASE_URL);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(400);
    const body = await res.json();
    expect(body.error).toContain("Invalid");
  });

  it("returns 400 when shop format is invalid", async () => {
    const req = makeGetRequest(`${BASE_URL}?shop=not-valid`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(400);
  });

  it("returns CORS headers on all responses", async () => {
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}&chartId=abc`);
    vi.mocked(db.sizeChart.findFirst).mockResolvedValueOnce(null);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });

  it("returns 204 for OPTIONS preflight", async () => {
    const req = makeOptionsRequest(BASE_URL);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(204);
  });

  it("returns 404 when chartId is provided but not found", async () => {
    vi.mocked(db.sizeChart.findFirst).mockResolvedValueOnce(null);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&chartId=nonexistent`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(404);
    const body = await res.json();
    expect(body.error).toContain("not found");
  });

  it("returns chart data when chartId is found", async () => {
    const chart = makeSizeChart();
    vi.mocked(db.sizeChart.findFirst).mockResolvedValueOnce(chart as never);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&chartId=chart-1`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.id).toBe("chart-1");
    expect(body.name).toBe("Test Chart");
    expect(body.data.headers).toEqual(["Size", "Chest", "Waist", "Hips"]);
    expect(body.data.rows.length).toBe(3);
  });

  it("returns 400 when no lookup params are provided (no chartId, productId, collectionId)", async () => {
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(400);
    const body = await res.json();
    expect(body.error).toContain("required");
  });

  it("returns chart via productId assignment", async () => {
    const assignment = makeChartAssignment();
    vi.mocked(db.chartAssignment.findMany).mockResolvedValueOnce([
      assignment as never,
    ]);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&productId=12345`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.id).toBe("chart-1");
    expect(body.assignmentType).toBe("product");
  });

  it("returns 404 when no assignments match", async () => {
    vi.mocked(db.chartAssignment.findMany).mockResolvedValueOnce([]);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&productId=99999`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(404);
  });

  it("respects assignment priority (product > collection > all)", async () => {
    const productAssignment = makeChartAssignment({
      id: "a1",
      assignmentType: "product",
      assignmentValue: "12345",
      sizeChart: makeSizeChart({ id: "chart-product", name: "Product Chart" }),
    });
    const allAssignment = makeChartAssignment({
      id: "a2",
      assignmentType: "all",
      assignmentValue: "*",
      sizeChart: makeSizeChart({ id: "chart-all", name: "All Chart" }),
    });
    vi.mocked(db.chartAssignment.findMany).mockResolvedValueOnce([
      allAssignment as never,
      productAssignment as never,
    ]);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&productId=12345`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.id).toBe("chart-product");
  });

  it("handles malformed chart data JSON gracefully", async () => {
    const chart = makeSizeChart({ data: "not-json{{{" });
    vi.mocked(db.sizeChart.findFirst).mockResolvedValueOnce(chart as never);
    const req = makeGetRequest(
      `${BASE_URL}?shop=${TEST_SHOP}&chartId=chart-1`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    // Should fall back to default empty data
    expect(body.data.headers).toEqual([]);
    expect(body.data.rows).toEqual([]);
  });
});

