}));

import { loader } from "~/routes/api.widget-config";
import db from "~/db.server";

const BASE_URL = "http://localhost:3000/api/widget-config";

beforeEach(() => {
  vi.clearAllMocks();
});

describe("GET /api/widget-config", () => {
