    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(400);
  });

  it("returns 400 for invalid shop format", async () => {
    const req = makeGetRequest(`${BASE_URL}?shop=bad-domain.com`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(400);
  });

