    vi.mocked(db.widgetConfig.findUnique).mockResolvedValueOnce(null);
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });

  it("returns default config when none saved", async () => {
    vi.mocked(db.widgetConfig.findUnique).mockResolvedValueOnce(null);
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.config).toBeDefined();
    expect(body.config.displayMode).toBe("popup");
    expect(body.config.primaryColor).toBe("#000000");
    expect(body.config.heading).toBe("Size Guide");
  });

  it("returns saved config when it exists", async () => {
    const config = makeWidgetConfig({
      primaryColor: "#ff0000",
      heading: "Custom Heading",
    });
    vi.mocked(db.widgetConfig.findUnique).mockResolvedValueOnce(config as never);
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.config.primaryColor).toBe("#ff0000");
    expect(body.config.heading).toBe("Custom Heading");
  });

  it("includes Cache-Control header (5-min)", async () => {
    vi.mocked(db.widgetConfig.findUnique).mockResolvedValueOnce(null);
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    const cc = res.headers.get("Cache-Control");
    expect(cc).toContain("max-age=300");
  });

  it("sanitizes custom CSS in response", async () => {
    const config = makeWidgetConfig({
      customCss: "@import url('evil.css'); body { color: red; }",
    });
    vi.mocked(db.widgetConfig.findUnique).mockResolvedValueOnce(config as never);
    const req = makeGetRequest(`${BASE_URL}?shop=${TEST_SHOP}`);
    const res = await loader({ request: req, params: {}, context: {} });
    const body = await res.json();
    expect(body.config.customCss).not.toContain("@import");
    expect(body.config.customCss).toContain("color: red");
  });
});

