import { action, loader } from "~/routes/api.recommend";
import db from "~/db.server";

const BASE_URL = "http://localhost:3000/api/recommend";

function validBody(overrides: Record<string, unknown> = {}) {
  return {
    shop: TEST_SHOP,
    chartId: "chart-1",
    height: 175,
    weight: 75,
    unit: "metric",
    gender: "male",
    bodyType: "average",
    ...overrides,
  };
