function setupDbMocks() {
  vi.mocked(db.recommenderConfig.findUnique).mockResolvedValue(
    makeRecommenderConfig() as never,
  );
  vi.mocked(db.subscription.findUnique).mockResolvedValue(
    makeSubscription() as never,
  );
  vi.mocked(db.sizeChart.findFirst).mockResolvedValue(
    makeSizeChart() as never,
  );
