      `${BASE_URL}?shop=${TEST_SHOP}&productId=12345`,
    );
    const res = await loader({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.id).toBe("chart-product");
  });

  it("handles malformed chart data JSON gracefully", async () => {
