    });
    const res = await action({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
  });

  it("accepts Shopify GID format for productId", async () => {
    const req = makePostRequest(BASE_URL, {
      shop: TEST_SHOP,
      eventType: "view",
      productId: "gid://shopify/Product/1234567890",
    });
    const res = await action({ request: req, params: {}, context: {} });
    expect(res.status).toBe(200);
  });

  it("returns 400 when shop is missing", async () => {
