import { describe, it, expect } from "vitest";
import { estimateMeasurements, recommendSize } from "~/lib/ai.server";
import type { RecommendInput } from "~/lib/ai.server";

// ---------------------------------------------------------------------------
// Sample chart data for testing recommendations
// ---------------------------------------------------------------------------

const SAMPLE_CHART: RecommendInput["chartData"] = {
  headers: ["Size", "Chest", "Waist", "Hips"],
  rows: [
    { Size: "S", Chest: "86-90", Waist: "71-75", Hips: "86-90" },
    { Size: "M", Chest: "91-96", Waist: "76-81", Hips: "91-96" },
    { Size: "L", Chest: "97-102", Waist: "82-87", Hips: "97-102" },
    { Size: "XL", Chest: "103-108", Waist: "88-93", Hips: "103-108" },
  ],
};

describe("estimateMeasurements", () => {
  it("returns all expected measurement keys", () => {
    const result = estimateMeasurements(175, 75, "male", "regular");
    expect(result).toHaveProperty("chest");
    expect(result).toHaveProperty("waist");
    expect(result).toHaveProperty("hips");
    expect(result).toHaveProperty("shoulder");
    expect(result).toHaveProperty("armLength");
    expect(result).toHaveProperty("inseam");
    expect(result).toHaveProperty("height");
  });

  it("returns numeric values for all measurements", () => {
    const result = estimateMeasurements(175, 75, "male", "regular");
    for (const [key, value] of Object.entries(result)) {
      expect(typeof value).toBe("number");
      expect(isNaN(value)).toBe(false);
    }
  });

  it("preserves input height in output", () => {
    const result = estimateMeasurements(180, 80, "male", "regular");
    expect(result.height).toBe(180);
  });

  it("produces different measurements for male vs female", () => {
    const male = estimateMeasurements(170, 65, "male", "regular");
    const female = estimateMeasurements(170, 65, "female", "regular");
    expect(male.chest).not.toBe(female.chest);
    expect(male.hips).not.toBe(female.hips);
  });

  it("slim body type has smaller chest than plus", () => {
    const slim = estimateMeasurements(175, 75, "male", "slim");
    const plus = estimateMeasurements(175, 75, "male", "plus");
    expect(slim.chest).toBeLessThan(plus.chest);
  });

  it("athletic body type has smaller waist than regular", () => {
    const athletic = estimateMeasurements(175, 75, "male", "athletic");
    const regular = estimateMeasurements(175, 75, "male", "regular");
    // Athletic has negative waist adjustment, but BMI delta also plays a role.
    // At BMI ~24.5 (above 22), the (1 + adj.waist) multiplier for athletic
    // should produce a smaller waist increment than regular.
    // With bmiFactor * (1 + (-0.05)) vs bmiFactor * (1 + 0), athletic < regular
    expect(athletic.waist).toBeLessThan(regular.waist);
  });

  it("athletic body type has larger shoulder than regular", () => {
    const athletic = estimateMeasurements(175, 75, "male", "athletic");
    const regular = estimateMeasurements(175, 75, "male", "regular");
    expect(athletic.shoulder).toBeGreaterThan(regular.shoulder);
  });

  it("lower weight produces smaller chest measurement", () => {
    const light = estimateMeasurements(175, 55, "male", "regular");
    const heavy = estimateMeasurements(175, 95, "male", "regular");
    expect(light.chest).toBeLessThan(heavy.chest);
  });

  it("measurements are rounded to 1 decimal place", () => {
    const result = estimateMeasurements(175, 75, "male", "regular");
    for (const [key, value] of Object.entries(result)) {
      if (key === "height") continue;
      const decimals = String(value).split(".")[1];
      expect(!decimals || decimals.length <= 1).toBe(true);
    }
  });
});

describe("recommendSize", () => {
  it("returns a recommended size for valid input", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: SAMPLE_CHART,
    });
    expect(result.recommendedSize).toBeTruthy();
    expect(["S", "M", "L", "XL"]).toContain(result.recommendedSize);
  });

  it("confidence is between 0 and 100", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: SAMPLE_CHART,
    });
    expect(result.confidence).toBeGreaterThanOrEqual(0);
    expect(result.confidence).toBeLessThanOrEqual(100);
  });

  it("returns estimatedMeasurements", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: SAMPLE_CHART,
    });
    expect(result.estimatedMeasurements).toBeDefined();
    expect(result.estimatedMeasurements.chest).toBeGreaterThan(0);
  });

  it("alternatives are filtered by confidence > 5%", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: SAMPLE_CHART,
    });
    for (const alt of result.alternatives) {
      expect(alt.confidence).toBeGreaterThan(5);
    }
  });

  it("returns empty string and 0 confidence for empty rows", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: { headers: ["Size", "Chest"], rows: [] },
    });
    expect(result.recommendedSize).toBe("");
    expect(result.confidence).toBe(0);
  });

  it("returns empty string and 0 confidence for empty headers", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: { headers: [], rows: [{ Size: "M", Chest: "92" }] },
    });
    expect(result.recommendedSize).toBe("");
    expect(result.confidence).toBe(0);
  });

  it("handles chart with only size column (no measurements)", () => {
    const result = recommendSize({
      height: 175,
      weight: 75,
      gender: "male",
      bodyType: "regular",
      chartData: {
        headers: ["Size"],
        rows: [{ Size: "S" }, { Size: "M" }, { Size: "L" }],
      },
    });
    // No measurement columns to match against, should return empty
    expect(result.recommendedSize).toBe("");
    expect(result.confidence).toBe(0);
  });

  it("handles range values in chart (e.g. '86-90')", () => {
    const result = recommendSize({
      height: 170,
      weight: 65,
      gender: "female",
      bodyType: "slim",
      chartData: SAMPLE_CHART,
    });
    // Should still produce a valid recommendation
    expect(result.recommendedSize).toBeTruthy();
    expect(result.confidence).toBeGreaterThan(0);
  });

  it("different body types get different recommendations for edge cases", () => {
    const slim = recommendSize({
      height: 180,
      weight: 80,
      gender: "male",
      bodyType: "slim",
      chartData: SAMPLE_CHART,
    });
    const plus = recommendSize({
      height: 180,
      weight: 80,
      gender: "male",
      bodyType: "plus",
      chartData: SAMPLE_CHART,
    });
    // They might get the same size but different confidences, or different sizes
    const sameSize = slim.recommendedSize === plus.recommendedSize;
    const sameConfidence = slim.confidence === plus.confidence;
    // At least one should differ
    expect(sameSize && sameConfidence).toBe(false);
  });
});

