                        </Text>
                      </BlockStack>
                    </BlockStack>
                  </BlockStack>
                )}
              </Box>
            </Card>
          </BlockStack>
        </Layout.Section>

        {/* ================================================================ */}
        {/* SIDEBAR (1/3)                                                     */}
        {/* ================================================================ */}
        <Layout.Section variant="oneThird">
          <ChartSidebar
            data={chartData}
            status={status}
            category={category}
            name={name}
            assignmentCount={assignments.length}
            createdAt={chart?.createdAt}
            updatedAt={chart?.updatedAt}
            isNew={isNew}
