        <BlockStack gap="300">
          <Text as="h2" variant="headingMd" fontWeight="semibold">
            Preview
          </Text>

          <InlineStack gap="200">
            <Badge>{data.units.default}</Badge>
            <Badge tone="info">{category}</Badge>
          </InlineStack>

          <Box
            borderWidth="025"
            borderColor="border"
            borderRadius="200"
