        </BlockStack>
      </Card>

      {/* Actions card */}
      {!isNew && (
        <Card>
          <BlockStack gap="300">
            <Text as="h2" variant="headingMd" fontWeight="semibold">
              Actions
            </Text>

            <Button
              onClick={onDuplicate}
              loading={isDuplicating}
              disabled={isDuplicating}
              fullWidth
            >
              Duplicate chart
            </Button>

            <Button
              tone="critical"
              variant="plain"
              onClick={onShowDeleteConfirm}
              fullWidth
            >
              Delete chart
            </Button>
          </BlockStack>
        </Card>
      )}

      {/* Info card */}
      {!isNew && (createdAt || updatedAt) && (
        <Card>
          <BlockStack gap="200">
            <Text as="h2" variant="headingMd" fontWeight="semibold">
              Info
            </Text>
            {createdAt && (
              <InlineStack align="space-between">
                <Text as="span" variant="bodySm" tone="subdued">Created</Text>
                <Text as="span" variant="bodySm">{formatDate(createdAt)}</Text>
              </InlineStack>
            )}
            {updatedAt && (
              <>
                <Divider />
                <InlineStack align="space-between">
                  <Text as="span" variant="bodySm" tone="subdued">Modified</Text>
                  <Text as="span" variant="bodySm">{formatDate(updatedAt)}</Text>
                </InlineStack>
              </>
            )}
          </BlockStack>
        </Card>
      )}

      {/* Delete confirmation modal */}
      <Modal
        open={showDeleteConfirm}
        onClose={onHideDeleteConfirm}
        title="Delete chart"
        primaryAction={{
          content: "Delete chart",
          destructive: true,
          onAction: onDelete,
        }}
        secondaryActions={[{ content: "Cancel", onAction: onHideDeleteConfirm }]}
      >
        <Modal.Section>
          <BlockStack gap="200">
            <Text as="p" variant="bodyMd">
              Are you sure you want to delete <strong>{name}</strong>?
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              This will permanently delete the chart and all its product assignments. This action cannot be undone.
            </Text>
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Widget hint */}
      <Box padding="300" background="bg-surface-secondary" borderRadius="200">
        <Text as="p" variant="bodySm" tone="subdued">
          Add the Size Chart widget block in your theme editor to display charts on product pages.
        </Text>
      </Box>
    </BlockStack>
  );
}

