  categories: string[];
  isLoading: boolean;
  fetcher: ReturnType<typeof useFetcher<typeof action>>;
}

function TemplatePicker({ templates, categories, isLoading, fetcher }: TemplatePickerProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

