import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate, useSearchParams } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  Box,
  Divider,
  InlineGrid,
  Modal,
  ProgressBar,
  TextField,
  Select,
  Checkbox,
  Pagination,
  EmptyState,
  Icon,
} from "@shopify/polaris";
import { SearchIcon } from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, canCreateChart } from "../lib/plans";
import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";

const PAGE_SIZE = 25;

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const url = new URL(request.url);
  const page = Math.max(1, parseInt(url.searchParams.get("page") ?? "1", 10));

  const [charts, totalCount, subscription] = await Promise.all([
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      include: { assignments: true },
      take: PAGE_SIZE,
      skip: (page - 1) * PAGE_SIZE,
    }),
    db.sizeChart.count({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
    name: t.name,
    category: t.category,
    gender: t.gender,
    rowCount: t.data.rows.length,
  }));
  const categories = getCategories();

  return {
    charts,
    totalCount,
    page,
    plan,
    templates,
    categories,
    canCreate: canCreateChart(plan.id, totalCount),
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "create-from-template": {
        const templateName = formData.get("templateName") as string;
        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
        if (!template) return { error: "Template not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let name = template.name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) name = `${template.name} (${Date.now().toString(36)})`;

        const created = await db.sizeChart.create({
          data: {
            shop,
            name,
            category: template.category,
            data: JSON.stringify(template.data),
            status: "active",
          },
        });
        return { ok: true, message: `"${name}" created successfully`, redirectId: created.id };
      }

      case "create-blank": {
        const name = (formData.get("name") as string) || "Untitled Size Chart";
        const category = (formData.get("category") as string) || "general";

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let uniqueName = name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;

        const defaultData = {
          headers: ["Size", "Chest", "Waist", "Hips"],
          units: { default: "in", available: ["in", "cm"] },
          rows: [
            { Size: "S", Chest: "", Waist: "", Hips: "" },
            { Size: "M", Chest: "", Waist: "", Hips: "" },
            { Size: "L", Chest: "", Waist: "", Hips: "" },
          ],
        };

        const created = await db.sizeChart.create({
          data: {
            shop,
            name: uniqueName,
            category,
            data: JSON.stringify(defaultData),
            status: "draft",
          },
        });
        return { ok: true, message: `"${uniqueName}" created`, redirectId: created.id };
      }

      case "delete": {
        const id = formData.get("id") as string;
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return { ok: true, message: "Chart deleted" };
      }

      case "import-csv": {
        const csvRaw = formData.get("csvData") as string;
        const chartName = (formData.get("name") as string) || "Imported Size Chart";
        const category = (formData.get("category") as string) || "general";

        if (!csvRaw?.trim()) return { error: "CSV data is required" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
        }

        const lines = csvRaw.trim().split(/\r?\n/).filter((l) => l.trim());
        if (lines.length < 2) return { error: "CSV must have a header row and at least one data row." };

        const parseRow = (line: string): string[] => {
          const result: string[] = [];
          let current = "";
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const ch = line[i];
            if (ch === '"') {
              if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
              else { inQuotes = !inQuotes; }
            } else if (ch === "," && !inQuotes) {
              result.push(current.trim());
              current = "";
            } else {
              current += ch;
            }
          }
          result.push(current.trim());
          return result;
        };

        const headers = parseRow(lines[0]);
        if (headers.length < 1) return { error: "Could not parse CSV headers." };

        const rows = lines.slice(1).map((line) => {
          const cells = parseRow(line);
          const row: Record<string, string> = {};
          headers.forEach((h, i) => { row[h] = cells[i] ?? ""; });
          return row;
        });

        const data = {
          headers,
          units: { default: "in", available: ["in", "cm"] },
          rows,
        };

        let uniqueName = chartName;
        const existingName = await db.sizeChart.findUnique({ where: { shop_name: { shop, name: chartName } } });
        if (existingName) uniqueName = `${chartName} (${Date.now().toString(36)})`;

        const created = await db.sizeChart.create({
          data: { shop, name: uniqueName, category, data: JSON.stringify(data), status: "draft" },
        });
        return { ok: true, message: `Imported "${uniqueName}"`, redirectId: created.id };
      }

      case "duplicate": {
        const sourceId = formData.get("id") as string;
        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
        if (!source) return { error: "Chart not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return { error: "Chart limit reached. Upgrade your plan." };
        }

        const newName = `${source.name} (Copy)`;
        await db.sizeChart.create({
          data: {
            shop,
            name: newName,
            type: source.type,
            category: source.category,
            data: source.data,
            status: "draft",
          },
        });
        return { ok: true, message: `Duplicated as "${newName}"` };
      }

      case "toggle-status": {
        const chartId = formData.get("id") as string;
        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
        if (!chart) return { error: "Chart not found" };

        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
        return {
          ok: true,
          message: `Chart ${newStatus === "active" ? "published" : "unpublished"}`,
        };
      }

      case "bulk-publish": {
        const chartIds = (formData.get("chartIds") as string).split(",").filter(Boolean);
        await db.sizeChart.updateMany({
          where: { id: { in: chartIds }, shop },
          data: { status: "active" },
        });
        return { ok: true, message: `${chartIds.length} chart${chartIds.length !== 1 ? "s" : ""} published` };
      }

      case "bulk-unpublish": {
        const chartIds = (formData.get("chartIds") as string).split(",").filter(Boolean);
        await db.sizeChart.updateMany({
          where: { id: { in: chartIds }, shop },
          data: { status: "draft" },
        });
        return { ok: true, message: `${chartIds.length} chart${chartIds.length !== 1 ? "s" : ""} unpublished` };
      }

      case "bulk-delete": {
        const chartIds = (formData.get("chartIds") as string).split(",").filter(Boolean);
        await db.sizeChart.deleteMany({
          where: { id: { in: chartIds }, shop },
        });
        return { ok: true, message: `${chartIds.length} chart${chartIds.length !== 1 ? "s" : ""} deleted` };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type ActionData =
  | { ok: true; message: string; redirectId?: string }
  | { error: string };

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const CATEGORY_LABELS: Record<string, string> = {
  tops: "Tops",
  bottoms: "Bottoms",
  dresses: "Dresses",
  shoes: "Shoes",
  kids: "Kids",
  rings: "Rings",
  sportswear: "Sportswear",
  general: "General",
};

const CATEGORY_ICONS: Record<string, string> = {
  tops: "👕",
  bottoms: "👖",
  dresses: "👗",
  shoes: "👟",
  kids: "🧒",
  rings: "💍",
  sportswear: "🏃",
  general: "📏",
};

const CATEGORY_SELECT_OPTIONS = [
  { label: "General", value: "general" },
  { label: "Tops", value: "tops" },
  { label: "Bottoms", value: "bottoms" },
  { label: "Dresses", value: "dresses" },
  { label: "Shoes", value: "shoes" },
  { label: "Kids", value: "kids" },
  { label: "Rings", value: "rings" },
  { label: "Sportswear", value: "sportswear" },
];

const SORT_OPTIONS = [
  { label: "Newest first", value: "newest" },
  { label: "Oldest first", value: "oldest" },
  { label: "Name A–Z", value: "name_asc" },
  { label: "Name Z–A", value: "name_desc" },
];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// TemplatePicker sub-component
// ---------------------------------------------------------------------------

interface TemplatePickerProps {
  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
  categories: string[];
  isLoading: boolean;
  fetcher: ReturnType<typeof useFetcher<typeof action>>;
}

function TemplatePicker({ templates, categories, isLoading, fetcher }: TemplatePickerProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  const filteredTemplates =
    selectedCategory === "all"
      ? templates
      : templates.filter((t) => t.category === selectedCategory);

  return (
    <BlockStack gap="500">
      {/* Blank chart option — always first */}
      <Card>
        <InlineStack gap="400" align="space-between" blockAlign="center">
          <BlockStack gap="100">
            <Text as="p" variant="bodyMd" fontWeight="semibold">
              Blank chart
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Start with an empty table and add your own columns and sizes
            </Text>
          </BlockStack>
          <fetcher.Form method="post">
            <input type="hidden" name="intent" value="create-blank" />
            <input type="hidden" name="name" value="Untitled Size Chart" />
            <input type="hidden" name="category" value="general" />
            <Button submit loading={isLoading}>
              Create blank
            </Button>
          </fetcher.Form>
        </InlineStack>
      </Card>

      <Divider />

      {/* Category filter */}
      <BlockStack gap="300">
        <Text as="p" variant="bodyMd" fontWeight="semibold">
          Start from a template
        </Text>
        <InlineStack gap="200" wrap>
          <Button
            variant={selectedCategory === "all" ? "primary" : undefined}
            size="slim"
            onClick={() => setSelectedCategory("all")}
          >
            All
          </Button>
          {categories.map((cat) => (
            <Button
              key={cat}
              variant={selectedCategory === cat ? "primary" : undefined}
              size="slim"
              onClick={() => setSelectedCategory(cat)}
            >
              {CATEGORY_ICONS[cat] ?? "📏"} {CATEGORY_LABELS[cat] ?? cat}
            </Button>
          ))}
        </InlineStack>
      </BlockStack>

      {/* Template grid */}
      {filteredTemplates.length > 0 ? (
        <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="300">
          {filteredTemplates.map((template) => (
            <Card key={template.name}>
              <BlockStack gap="300">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="span" variant="bodyMd">
                    {CATEGORY_ICONS[template.category] ?? "📏"}
                  </Text>
                  <Text as="p" variant="bodyMd" fontWeight="semibold">
                    {template.name}
                  </Text>
                </InlineStack>
                <InlineStack gap="200" blockAlign="center">
                  <Badge tone="info">
                    {CATEGORY_LABELS[template.category] ?? template.category}
                  </Badge>
                  <Text as="span" variant="bodySm" tone="subdued">
                    {template.rowCount} sizes
                  </Text>
                </InlineStack>
                <fetcher.Form method="post">
                  <input type="hidden" name="intent" value="create-from-template" />
                  <input type="hidden" name="templateName" value={template.name} />
                  <Button variant="primary" submit loading={isLoading} fullWidth>
                    Use template
                  </Button>
                </fetcher.Form>
              </BlockStack>
            </Card>
          ))}
        </InlineGrid>
      ) : (
        <Text as="p" variant="bodyMd" tone="subdued">
          No templates in this category.
        </Text>
      )}
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export default function SizeCharts() {
  const { charts, totalCount, page, plan, templates, categories, canCreate } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const rowFetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const [showTemplates, setShowTemplates] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importName, setImportName] = useState("Imported Size Chart");
  const [importCategory, setImportCategory] = useState("general");
  const [importCsvText, setImportCsvText] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);

  // Filters (client-side on current page)
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [sortBy, setSortBy] = useState("newest");

  // Bulk selection
  const [selectedCharts, setSelectedCharts] = useState<Set<string>>(new Set());

  const isLoading = fetcher.state !== "idle";
  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
  const startItem = (page - 1) * PAGE_SIZE + 1;
  const endItem = Math.min(page * PAGE_SIZE, totalCount);

  const publishedCount = charts.filter((c) => c.status === "active").length;
  const maxCharts = plan.limits.maxCharts;
  const isFreePlan = plan.id === "free";
  const progressPct = maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
  const progressTone: "primary" | "critical" = publishedCount >= maxCharts && maxCharts > 0 ? "critical" : "primary";

  // Handle fetcher responses
  useEffect(() => {
    if (!fetcher.data) return;
    const data = fetcher.data as ActionData;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message);
      setSelectedCharts(new Set());
      if ("redirectId" in data && data.redirectId) {
        navigate(`/app/size-charts/${data.redirectId}`);
      } else {
        setShowTemplates(false);
        setShowImport(false);
        setImportCsvText("");
        setImportName("Imported Size Chart");
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [fetcher.data, shopify, navigate]);

  // Handle row action responses (toggle-status, duplicate, delete)
  useEffect(() => {
    if (!rowFetcher.data) return;
    const data = rowFetcher.data as ActionData;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message);
      setDeleteTarget(null);
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [rowFetcher.data, shopify]);

  const handleDeleteChart = (id: string) => {
    const formData = new FormData();
    formData.set("intent", "delete");
    formData.set("id", id);
    rowFetcher.submit(formData, { method: "post" });
    setDeleteTarget(null);
  };

  // Apply client-side filters + sort
  const filteredCharts = charts
    .filter((chart) => {
      const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
      const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
      const matchesSearch =
        searchQuery.trim() === "" ||
        chart.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesStatus && matchesCategory && matchesSearch;
    })
    .sort((a, b) => {
      if (sortBy === "oldest") return new Date(a.updatedAt).getTime() - new Date(b.updatedAt).getTime();
      if (sortBy === "name_asc") return a.name.localeCompare(b.name);
      if (sortBy === "name_desc") return b.name.localeCompare(a.name);
      return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(); // newest
    });

  function clearFilters() {
    setStatusFilter("all");
    setCategoryFilter("all");
    setSearchQuery("");
    setSortBy("newest");
  }

  function goToPage(newPage: number) {
    const params = new URLSearchParams(searchParams);
    params.set("page", String(newPage));
    setSearchParams(params);
    setSelectedCharts(new Set());
  }

  function toggleSelectAll() {
    if (selectedCharts.size === filteredCharts.length) {
      setSelectedCharts(new Set());
    } else {
      setSelectedCharts(new Set(filteredCharts.map((c) => c.id)));
    }
  }

  function toggleSelectChart(id: string) {
    setSelectedCharts((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleBulkAction(intent: "bulk-publish" | "bulk-unpublish" | "bulk-delete") {
    if (selectedCharts.size === 0) return;
    const formData = new FormData();
    formData.set("intent", intent);
    formData.set("chartIds", Array.from(selectedCharts).join(","));
    fetcher.submit(formData, { method: "post" });
  }

  const categoryFilterOptions = [
    { label: "All categories", value: "all" },
    ...categories.map((cat) => ({ label: CATEGORY_LABELS[cat] ?? cat, value: cat })),
  ];

  const statusFilterOptions = [
    { label: "All status", value: "all" },
    { label: "Active", value: "active" },
    { label: "Draft", value: "draft" },
  ];

  const hasSelection = selectedCharts.size > 0;
  const allSelected = filteredCharts.length > 0 && selectedCharts.size === filteredCharts.length;

  return (
    <Page
      title="Size Charts"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button
          variant="primary"
          onClick={() => {
            setShowTemplates(true);
            setShowImport(false);
          }}
          disabled={!canCreate || isLoading}
        >
          {canCreate ? "Create chart" : `Limit reached (${plan.limits.maxCharts})`}
        </Button>
      }
      secondaryActions={[
        {
          content: "Import CSV",
          onAction: () => {
            setShowImport(true);
            setShowTemplates(false);
          },
        },
      ]}
    >
      <Layout>

        {/* ================================================================ */}
        {/* PLAN LIMIT BANNER                                                 */}
        {/* ================================================================ */}
        {!canCreate && (
          <Layout.Section>
            <Banner tone="warning" title="Chart limit reached">
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">
                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
                  {plan.name} plan. Upgrade to Starter for unlimited charts.
                </Text>
                <Button variant="primary" onClick={() => navigate("/app/pricing")}>
                  Upgrade plan
                </Button>
              </BlockStack>
            </Banner>
          </Layout.Section>
        )}

        {/* ================================================================ */}
        {/* CREATE CHART MODAL                                                */}
        {/* ================================================================ */}
        <Modal
          open={showTemplates}
          onClose={() => setShowTemplates(false)}
          title="Create a size chart"
        >
          <Modal.Section>
            <TemplatePicker
              templates={templates}
              categories={categories}
              isLoading={isLoading}
              fetcher={fetcher}
            />
          </Modal.Section>
        </Modal>

        {/* ================================================================ */}
        {/* CSV IMPORT MODAL                                                  */}
        {/* ================================================================ */}
        <Modal
          open={showImport}
          onClose={() => setShowImport(false)}
          title="Import size chart from CSV"
          primaryAction={{
            content: "Import chart",
            onAction: () => {
              const formData = new FormData();
              formData.set("intent", "import-csv");
              formData.set("name", importName);
              formData.set("category", importCategory);
              formData.set("csvData", importCsvText);
              fetcher.submit(formData, { method: "post" });
            },
            loading: isLoading,
            disabled: !importCsvText.trim(),
          }}
          secondaryActions={[{ content: "Cancel", onAction: () => setShowImport(false) }]}
        >
          <Modal.Section>
            <BlockStack gap="400">
              <Text as="p" variant="bodyMd" tone="subdued">
                Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
              </Text>

              <Banner tone="info">
                <Text as="p" variant="bodySm">
                  {`Expected format: Size,Chest,Waist,Hips — one row per size (XS, S, M, L, XL, etc.)`}
                </Text>
              </Banner>

              <InlineGrid columns={{ xs: 1, sm: ["twoThirds", "oneThird"] }} gap="400">
                <TextField
                  label="Chart name"
                  value={importName}
                  onChange={setImportName}
                  placeholder="e.g. Women's Tops"
                  autoComplete="off"
                />
                <Select
                  label="Category"
                  options={CATEGORY_SELECT_OPTIONS}
                  value={importCategory}
                  onChange={setImportCategory}
                />
              </InlineGrid>

              <TextField
                label="CSV data"
                value={importCsvText}
                onChange={setImportCsvText}
                multiline={8}
                placeholder={"Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38"}
                autoComplete="off"
              />

              <Text as="p" variant="bodySm" tone="subdued">
                Chart will be created as a draft — review and publish when ready.
              </Text>
            </BlockStack>
          </Modal.Section>
        </Modal>

        {/* ================================================================ */}
        {/* MAIN CHART LIST                                                   */}
        {/* ================================================================ */}
        <Layout.Section>
          <Card padding="0">
            <BlockStack gap="0">

              {/* Header with search + filters */}
              <Box padding="400" paddingBlockEnd="300">
                <BlockStack gap="300">

                  {/* Search bar */}
                  <TextField
                    label=""
                    labelHidden
                    prefix={<Icon source={SearchIcon} />}
                    placeholder="Search charts by name..."
                    value={searchQuery}
                    onChange={setSearchQuery}
                    autoComplete="off"
                    clearButton
                    onClearButtonClick={() => setSearchQuery("")}
                  />

                  {/* Filter row */}
                  <InlineStack gap="300" wrap>
                    <Box minWidth="130px">
                      <Select
                        label=""
                        labelHidden
                        options={statusFilterOptions}
                        value={statusFilter}
                        onChange={(v) => setStatusFilter(v as "all" | "active" | "draft")}
                      />
                    </Box>
                    <Box minWidth="150px">
                      <Select
                        label=""
                        labelHidden
                        options={categoryFilterOptions}
                        value={categoryFilter}
                        onChange={setCategoryFilter}
                      />
                    </Box>
                    <Box minWidth="150px">
                      <Select
                        label=""
                        labelHidden
                        options={SORT_OPTIONS}
                        value={sortBy}
                        onChange={setSortBy}
                      />
                    </Box>
                    {(statusFilter !== "all" || categoryFilter !== "all" || searchQuery !== "" || sortBy !== "newest") && (
                      <Button variant="plain" onClick={clearFilters}>
                        Clear filters
                      </Button>
                    )}
                  </InlineStack>
                </BlockStack>
              </Box>

              <Divider />

              {/* Bulk action bar */}
              {hasSelection && (
                <>
                  <Box
                    padding="300"
                    paddingInlineStart="400"
                    paddingInlineEnd="400"
                    background="bg-surface-selected"
                  >
                    <InlineStack gap="300" blockAlign="center" align="space-between">
                      <Text as="span" variant="bodyMd" fontWeight="semibold">
                        {selectedCharts.size} selected
                      </Text>
                      <InlineStack gap="200">
                        <Button
                          size="slim"
                          onClick={() => handleBulkAction("bulk-publish")}
                          loading={isLoading}
                        >
                          Publish selected
                        </Button>
                        <Button
                          size="slim"
                          onClick={() => handleBulkAction("bulk-unpublish")}
                          loading={isLoading}
                        >
                          Unpublish selected
                        </Button>
                        <Button
                          size="slim"
                          tone="critical"
                          onClick={() => handleBulkAction("bulk-delete")}
                          loading={isLoading}
                        >
                          Delete selected
                        </Button>
                      </InlineStack>
                    </InlineStack>
                  </Box>
                  <Divider />
                </>
              )}

              {/* Column header row */}
              {filteredCharts.length > 0 && (
                <>
                  <Box
                    padding="300"
                    paddingInlineStart="400"
                    paddingInlineEnd="400"
                    background="bg-surface-secondary"
                  >
                    <InlineStack gap="400" blockAlign="center">
                      <Box minWidth="20px">
                        <Checkbox
                          label=""
                          labelHidden
                          checked={allSelected}
                          onChange={toggleSelectAll}
                        />
                      </Box>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <Text as="span" variant="bodySm" fontWeight="semibold" tone="subdued">
                          CHART NAME
                        </Text>
                      </div>
                      <div style={{ width: "90px", textAlign: "center" }}>
                        <Text as="span" variant="bodySm" fontWeight="semibold" tone="subdued">
                          STATUS
                        </Text>
                      </div>
                      <div style={{ width: "110px", textAlign: "center" }}>
                        <Text as="span" variant="bodySm" fontWeight="semibold" tone="subdued">
                          ASSIGNMENTS
                        </Text>
                      </div>
                      <div style={{ width: "110px", textAlign: "right" }}>
                        <Text as="span" variant="bodySm" fontWeight="semibold" tone="subdued">
                          LAST UPDATED
                        </Text>
                      </div>
                      <div style={{ width: "190px" }} />
                    </InlineStack>
                  </Box>
                  <Divider />
                </>
              )}

              {/* Empty state — no charts at all */}
              {totalCount === 0 && (
                <Box padding="600">
                  <EmptyState
                    heading="Create your first size chart"
                    image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                    action={{
                      content: "Create chart",
                      onAction: () => setShowTemplates(true),
                    }}
                    secondaryAction={{
                      content: "Import CSV",
                      onAction: () => setShowImport(true),
                    }}
                  >
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Start by creating a size chart to help customers find the right size.
                      Reduce size-related returns by up to 40% — get started in under 3 minutes
                      using one of our pre-built templates.
                    </Text>
                  </EmptyState>
                </Box>
              )}

              {/* Empty state — filters applied but no results */}
              {totalCount > 0 && filteredCharts.length === 0 && (
                <Box padding="600">
                  <BlockStack gap="300" inlineAlign="center">
                    <Text as="h2" variant="headingMd">No charts match your filters</Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Try adjusting your search or filters to find what you are looking for.
                    </Text>
                    <Button onClick={clearFilters}>Clear filters</Button>
                  </BlockStack>
                </Box>
              )}

              {/* Chart rows */}
              {filteredCharts.map((chart, index) => (
                <div key={chart.id}>
                  <Box
                    padding="300"
                    paddingInlineStart="400"
                    paddingInlineEnd="400"
                    background={selectedCharts.has(chart.id) ? "bg-surface-selected" : "bg-surface"}
                  >
                    <InlineStack gap="400" blockAlign="center">
                      {/* Checkbox */}
                      <Box minWidth="20px">
                        <Checkbox
                          label=""
                          labelHidden
                          checked={selectedCharts.has(chart.id)}
                          onChange={() => toggleSelectChart(chart.id)}
                        />
                      </Box>

                      {/* Name + category */}
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <InlineStack gap="200" blockAlign="center" wrap={false}>
                          <Text as="span" variant="bodySm">
                            {CATEGORY_ICONS[chart.category] ?? "📏"}
                          </Text>
                          <Button
                            variant="plain"
                            onClick={() => navigate(`/app/size-charts/${chart.id}`)}
                            textAlign="left"
                          >
                            {chart.name}
                          </Button>
                          <Badge tone="info">
                            {CATEGORY_LABELS[chart.category] ?? chart.category}
                          </Badge>
                        </InlineStack>
                      </div>

                      {/* Status */}
                      <div style={{ width: "90px", textAlign: "center" }}>
                        <Badge tone={chart.status === "active" ? "success" : undefined}>
                          {chart.status === "active" ? "Active" : "Draft"}
                        </Badge>
                      </div>

                      {/* Assignments */}
                      <div style={{ width: "110px", textAlign: "center" }}>
                        <Text as="span" variant="bodySm" tone="subdued">
                          {chart.assignments.length > 0
                            ? `${chart.assignments.length} rule${chart.assignments.length !== 1 ? "s" : ""}`
                            : "None"}
                        </Text>
                      </div>

                      {/* Last updated */}
                      <div style={{ width: "110px", textAlign: "right" }}>
                        <Text as="span" variant="bodySm" tone="subdued">
                          {formatDate(chart.updatedAt)}
                        </Text>
                      </div>

                      {/* Row actions */}
                      <div style={{ width: "190px" }}>
                        <InlineStack gap="100" align="end">
                          <Button
                            size="slim"
                            onClick={() => navigate(`/app/size-charts/${chart.id}`)}
                          >
                            Edit
                          </Button>

                          <rowFetcher.Form method="post">
                            <input type="hidden" name="intent" value="toggle-status" />
                            <input type="hidden" name="id" value={chart.id} />
                            <Button size="slim" submit loading={rowFetcher.state !== "idle"}>
                              {chart.status === "active" ? "Unpublish" : "Publish"}
                            </Button>
                          </rowFetcher.Form>

                          <rowFetcher.Form method="post">
                            <input type="hidden" name="intent" value="duplicate" />
                            <input type="hidden" name="id" value={chart.id} />
                            <Button size="slim" submit loading={rowFetcher.state !== "idle"}>
                              Duplicate
                            </Button>
                          </rowFetcher.Form>

                          <Button
                            size="slim"
                            tone="critical"
                            onClick={() => setDeleteTarget({ id: chart.id, name: chart.name })}
                          >
                            Delete
                          </Button>
                        </InlineStack>
                      </div>
                    </InlineStack>
                  </Box>
                  {index < filteredCharts.length - 1 && <Divider />}
                </div>
              ))}

              {/* Footer: count + pagination */}
              {totalCount > 0 && (
                <>
                  <Divider />
                  <Box padding="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="span" variant="bodySm" tone="subdued">
                        {totalCount > PAGE_SIZE
                          ? `Showing ${startItem}–${endItem} of ${totalCount} charts`
                          : `${totalCount} chart${totalCount !== 1 ? "s" : ""}`}
                      </Text>
                      {totalPages > 1 && (
                        <Pagination
                          hasPrevious={page > 1}
                          onPrevious={() => goToPage(page - 1)}
                          hasNext={page < totalPages}
                          onNext={() => goToPage(page + 1)}
                          label={`Page ${page} of ${totalPages}`}
                        />
                      )}
                    </InlineStack>
                  </Box>
                </>
              )}

            </BlockStack>
          </Card>
        </Layout.Section>

        {/* ================================================================ */}
        {/* PLAN USAGE BAR (free plan only)                                  */}
        {/* ================================================================ */}
        {isFreePlan && maxCharts > 0 && (
          <Layout.Section>
            <Card>
              <BlockStack gap="200">
                <InlineStack gap="300" blockAlign="center" align="space-between">
                  <InlineStack gap="200" blockAlign="center">
                    <Badge>{`${plan.name} Plan`}</Badge>
                    <Text as="span" variant="bodyMd">
                      {publishedCount} of {maxCharts} charts used
                    </Text>
                  </InlineStack>
                  <Button size="slim" onClick={() => navigate("/app/pricing")}>
                    Upgrade
                  </Button>
                </InlineStack>
                <ProgressBar progress={progressPct} size="small" tone={progressTone} />
                <Text as="span" variant="bodySm" tone="subdued">
                  {maxCharts - publishedCount > 0
                    ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                    : "Upgrade to publish more charts"}
                </Text>
              </BlockStack>
            </Card>
          </Layout.Section>
        )}

      </Layout>
    </Page>
  );
}

