// ---------------------------------------------------------------------------
// BodyTypeCard
// ---------------------------------------------------------------------------

function BodyTypeCard({
  bt,
  onToggle,
}: {
  bt: BodyTypeConfig;
  onToggle: (id: string, checked: boolean) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onToggle(bt.id, !bt.enabled)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onToggle(bt.id, !bt.enabled);
        }
      }}
      style={{ cursor: "pointer" }}
    >
      <Box
        borderWidth={bt.enabled ? "050" : "025"}
        borderColor={bt.enabled ? "border-focus" : "border"}
        borderRadius="300"
        background={bt.enabled ? "bg-surface-selected" : "bg-surface"}
        padding="400"
      >
        <BlockStack gap="200" inlineAlign="center">
          <div style={{ color: bt.enabled ? "var(--p-color-text-brand)" : "var(--p-color-icon-subdued)" }}>
            {BODY_TYPE_SVGS[bt.id]}
          </div>
          <Text as="p" variant="bodyMd" fontWeight={bt.enabled ? "semibold" : "regular"} alignment="center">
            {bt.label}
          </Text>
          <Text as="p" variant="bodySm" tone="subdued" alignment="center">
            {bt.description}
          </Text>
          {bt.enabled && <Badge tone="success">On</Badge>}
        </BlockStack>
      </Box>
    </div>
  );
}

