interface SelectCardOption {
  value: string;
  label: string;
  description: string;
}

function SelectCards({
  options,
  value,
  onChange,
  columns,
}: {
  options: SelectCardOption[];
  value: string;
  onChange: (v: string) => void;
  columns: number;
}) {
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        gap: "8px",
      }}
    >
      {options.map((opt) => {
        const isSelected = value === opt.value;
        return (
          <div
            key={opt.value}
