export default function WidgetCustomizer() {
  const { config: serverConfig } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const [config, setConfig] = useState<LocalConfig>({
    displayMode: serverConfig.displayMode,
    position: serverConfig.position,
    triggerType: serverConfig.triggerType,
    primaryColor: serverConfig.primaryColor,
    successColor: serverConfig.successColor,
    errorColor: serverConfig.errorColor,
    backgroundColor: serverConfig.backgroundColor,
    textColor: serverConfig.textColor,
    borderRadius: serverConfig.borderRadius,
    heading: serverConfig.heading,
    placeholder: serverConfig.placeholder,
    buttonText: serverConfig.buttonText,
    successMessage: serverConfig.successMessage,
    errorMessage: serverConfig.errorMessage,
    showRecommender: serverConfig.showRecommender,
    customCss: serverConfig.customCss,
  });

  const [previewMode, setPreviewMode] = useState<"desktop" | "mobile">("desktop");

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
    setConfig((prev) => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    const formData = new FormData();
    formData.set("displayMode", config.displayMode);
    formData.set("position", config.position);
    formData.set("triggerType", config.triggerType);
    formData.set("primaryColor", config.primaryColor);
    formData.set("successColor", config.successColor);
    formData.set("errorColor", config.errorColor);
    formData.set("backgroundColor", config.backgroundColor);
    formData.set("textColor", config.textColor);
    formData.set("borderRadius", config.borderRadius);
    formData.set("heading", config.heading);
    formData.set("placeholder", config.placeholder);
    formData.set("buttonText", config.buttonText);
    formData.set("successMessage", config.successMessage);
    formData.set("errorMessage", config.errorMessage);
    formData.set("showRecommender", config.showRecommender ? "true" : "false");
    formData.set("customCss", config.customCss);
    fetcher.submit(formData, { method: "post" });
  };

  const handleReset = () => {
    setConfig(DEFAULTS);
  };

  const showPosition = config.displayMode === "popup" || config.displayMode === "both";

  const displayModeOptions = [
    { value: "popup", label: "Popup", description: "Modal overlay — keeps product page clean" },
    { value: "inline", label: "Inline", description: "Embedded in product page — always visible" },
    { value: "both", label: "Both", description: "Inline summary + popup for full chart" },
  ];

  const triggerOptions = [
    { value: "button", label: "Button", description: "Prominent call-to-action button" },
    { value: "link", label: "Link", description: "Subtle text link, minimal footprint" },
    { value: "tab", label: "Tab", description: "Sticky edge tab, always accessible" },
  ];

  const positionOptions = [
    { label: "Bottom right", value: "bottom-right" },
    { label: "Bottom left", value: "bottom-left" },
    { label: "Top right", value: "top-right" },
    { label: "Top left", value: "top-left" },
  ];

  return (
    <Page
      title="Widget Customizer"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button variant="primary" onClick={handleSave} loading={isLoading}>
          Save changes
        </Button>
      }
    >
      <Layout>
        {/* ================================================================ */}
        {/* LEFT — Settings                                                   */}
        {/* ================================================================ */}
        <Layout.Section>
          <BlockStack gap="500">

            {/* Card 1: Display Mode */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Display Mode</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Choose how the size chart appears on your product pages.
                  </Text>
                </BlockStack>
                <SelectCards
                  options={displayModeOptions}
                  value={config.displayMode}
                  onChange={(v) => updateConfig("displayMode", v)}
                  columns={3}
                />
              </BlockStack>
            </Card>

            {/* Card 2: Trigger Style */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Trigger Style</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    How customers open the size chart widget.
                  </Text>
                </BlockStack>
                <SelectCards
                  options={triggerOptions}
                  value={config.triggerType}
                  onChange={(v) => updateConfig("triggerType", v)}
                  columns={3}
                />
              </BlockStack>
            </Card>

            {/* Card 3: Position (only for popup/both) */}
            {showPosition && (
              <Card>
                <BlockStack gap="400">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd" fontWeight="semibold">Popup Position</Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Where the popup trigger button appears on the product page.
                    </Text>
                  </BlockStack>
                  <div style={{ maxWidth: "300px" }}>
                    <Select
                      label="Position"
                      labelHidden
                      options={positionOptions}
                      value={config.position}
                      onChange={(v) => updateConfig("position", v)}
                    />
                  </div>
                </BlockStack>
              </Card>
            )}

            {/* Card 4: Colors */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Colors</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Match the widget to your store branding.
                  </Text>
                </BlockStack>
                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <ColorField
                    label="Primary color"
                    name="primaryColor"
                    value={config.primaryColor}
                    onChange={(v) => updateConfig("primaryColor", v)}
                  />
                  <ColorField
                    label="Background color"
                    name="backgroundColor"
                    value={config.backgroundColor}
                    onChange={(v) => updateConfig("backgroundColor", v)}
                  />
                  <ColorField
                    label="Text color"
                    name="textColor"
                    value={config.textColor}
                    onChange={(v) => updateConfig("textColor", v)}
                  />
                  <ColorField
                    label="Success color"
                    name="successColor"
                    value={config.successColor}
                    onChange={(v) => updateConfig("successColor", v)}
                  />
                  <ColorField
                    label="Error color"
                    name="errorColor"
                    value={config.errorColor}
                    onChange={(v) => updateConfig("errorColor", v)}
                  />
                </InlineGrid>
              </BlockStack>
            </Card>

            {/* Card 5: Border & Spacing */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Border &amp; Spacing</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Control the roundness of corners in the widget.
                  </Text>
                </BlockStack>
                <BlockStack gap="400">
                  <RangeSlider
                    label={`Border radius — ${config.borderRadius}px`}
                    value={Number(config.borderRadius) || 0}
                    min={0}
                    max={24}
                    step={1}
                    output
                    onChange={(val) => updateConfig("borderRadius", String(val as number))}
                  />
                  <InlineStack gap="300" blockAlign="center">
                    <Text as="p" variant="bodySm" tone="subdued">Presets:</Text>
                    {["0", "4", "8", "12", "24"].map((r) => (
                      <Tooltip key={r} content={`${r}px`}>
                        <div
                          role="button"
                          tabIndex={0}
                          onClick={() => updateConfig("borderRadius", r)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                              e.preventDefault();
                              updateConfig("borderRadius", r);
                            }
                          }}
                          style={{ cursor: "pointer" }}
                        >
                          <div
                            style={{
                              width: "36px",
                              height: "36px",
                              backgroundColor: config.borderRadius === r ? config.primaryColor : "#e3e5e7",
                              borderRadius: `${r}px`,
                              border: config.borderRadius === r
                                ? `2px solid ${config.primaryColor}`
                                : "2px solid transparent",
                              transition: "all 0.15s",
                            }}
                          />
                        </div>
                      </Tooltip>
                    ))}
                  </InlineStack>
                </BlockStack>
              </BlockStack>
            </Card>

            {/* Card 6: Text Content */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Text Content</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Customize the copy customers see in the widget.
                  </Text>
                </BlockStack>
                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <TextField
                    label="Widget heading"
                    value={config.heading}
                    onChange={(value) => updateConfig("heading", value)}
                    placeholder="Size Guide"
                    autoComplete="off"
                  />
                  <TextField
                    label="Button text"
                    value={config.buttonText}
                    onChange={(value) => updateConfig("buttonText", value)}
                    placeholder="Find My Size"
                    autoComplete="off"
                  />
                  <TextField
                    label="Placeholder text"
                    value={config.placeholder}
                    onChange={(value) => updateConfig("placeholder", value)}
                    placeholder="Select your size"
                    autoComplete="off"
                  />
                </InlineGrid>
                <Divider />
                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <TextField
                    label="Success message"
                    value={config.successMessage}
                    onChange={(value) => updateConfig("successMessage", value)}
                    placeholder="This size should fit you well!"
                    autoComplete="off"
                    helpText="Shown after a successful size recommendation"
                  />
                  <TextField
                    label="Error message"
                    value={config.errorMessage}
                    onChange={(value) => updateConfig("errorMessage", value)}
                    placeholder="We couldn't determine your size."
                    autoComplete="off"
                    helpText="Shown when a recommendation cannot be made"
                  />
                </InlineGrid>
              </BlockStack>
            </Card>

            {/* Card 7: Recommender toggle */}
            <Card>
              <BlockStack gap="300">
                <Text as="h2" variant="headingMd" fontWeight="semibold">AI Recommender</Text>
                <Checkbox
                  label="Show size recommender button"
                  checked={config.showRecommender}
                  onChange={(checked) => updateConfig("showRecommender", checked)}
                  helpText='Display a "Find My Size" button that lets customers get a personalized recommendation based on their measurements.'
                />
                {config.showRecommender && (
                  <Badge tone="success">Enabled — button visible in widget</Badge>
                )}
              </BlockStack>
            </Card>

            {/* Card 8: Custom CSS */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Custom CSS</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Advanced: inject custom styles into the widget. Styles are scoped to
                    .size-chart-widget — use this class as your root selector.
                  </Text>
                </BlockStack>
                <TextField
                  label="Custom CSS"
                  labelHidden
                  value={config.customCss}
                  onChange={(val) => updateConfig("customCss", val)}
                  multiline={6}
                  placeholder={`.size-chart-widget {\n  /* custom styles */\n}`}
                  autoComplete="off"
                  monospaced
                />
              </BlockStack>
            </Card>

          </BlockStack>
        </Layout.Section>

        {/* ================================================================ */}
        {/* RIGHT — Sticky Preview                                            */}
        {/* ================================================================ */}
        <Layout.Section variant="oneThird">
          <div style={{ position: "sticky", top: "64px" }}>
            <Card>
              <BlockStack gap="400">
                {/* Header row */}
                <InlineStack gap="200" align="space-between" blockAlign="center">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Live Preview</Text>
                  <InlineStack gap="100">
                    <Button
                      size="slim"
                      variant={previewMode === "desktop" ? "primary" : undefined}
                      onClick={() => setPreviewMode("desktop")}
                    >
                      Desktop
                    </Button>
                    <Button
                      size="slim"
                      variant={previewMode === "mobile" ? "primary" : undefined}
                      onClick={() => setPreviewMode("mobile")}
                    >
                      Mobile
                    </Button>
                  </InlineStack>
                </InlineStack>

                {/* Active config badges */}
                <InlineStack gap="150" wrap>
                  <Badge tone="info">{config.displayMode}</Badge>
                  <Badge tone="info">{config.triggerType}</Badge>
                  {showPosition && <Badge tone="info">{config.position}</Badge>}
                  <Badge tone={config.showRecommender ? "success" : "new"}>
                    {config.showRecommender ? "AI on" : "AI off"}
                  </Badge>
                </InlineStack>

                <Divider />

                {/* Preview */}
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    padding: "8px 0",
                    overflow: "hidden",
                  }}
                >
                  <WidgetPreview config={config} previewMode={previewMode} />
                </div>

                <Divider />

                {/* Reset */}
                <Button onClick={handleReset} variant="plain" tone="critical">
                  Reset to defaults
                </Button>
              </BlockStack>
            </Card>
          </div>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

