            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Your size charts and assignments are not affected.
              </Text>
            </Banner>
            <TextField
              label='Type "DELETE" to confirm'
              value={resetAppConfirm}
              onChange={(value) => setResetAppConfirm(value)}
              placeholder="DELETE"
              autoComplete="off"
              helpText="This field is case-sensitive."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

    </Page>
  );
}

import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  Divider,
  InlineGrid,
  TextField,
  Select,
  Box,
  Modal,
  List,
  Icon,
} from "@shopify/polaris";
import {
  StoreIcon,
  ChartVerticalIcon,
