                      </Box>
                    ))}
                  </BlockStack>
                </Card>
              </BlockStack>

              {/* ── FAQ section ───────────────────────────────────────────── */}
              <BlockStack gap="400">
                <Text as="h2" variant="headingLg">
                  Frequently asked questions
